def patch(source, key, replacement):
    pattern = r'(?m)^' + re.escape(key) + r'\s*=.*$'
    source, n = re.subn(pattern, lambda _: key+' = '+replacement, source, count=1)
    if n != 1: raise ValueError('Missing builder option: ' + key)
    return source

def run():
    OUTPUT.mkdir(parents=True, exist_ok=True)
    data = zlib.decompress(base64.b85decode(BUILDER_PAYLOAD)).decode('utf-8')
    report = []
    for part in PARTS:
        code = data
        for key, value in (
            ('PART',repr(part)),
            ('SHOW_ARMOR','False'),
            ('EXPORT_FBX','True'),
            ('AUTO_SAVE_BLEND','True'),
            ('ADD_STUDIO_CAMERA_AND_LIGHTS','False'),
            ('ANIMATE_LED_PREVIEW','False'),
            ('OUTPUT_DIR','OUTPUT_DIR_OVERRIDE'),
        ):
            code=patch(code,key,value)
        namespace = {'__name__':'__main__', '__file__':str(OUTPUT / ('builder_'+part+'.py')),
                     'OUTPUT_DIR_OVERRIDE': OUTPUT}
        print('\n[RoosterWorks] GENERATING:',part)
        try:
            exec(compile(code,namespace['__file__'],'exec'), namespace)
            pid = namespace['PART_ID']
            for suffix in ('.blend','_INTERMEDIATE.fbx'):
                target=OUTPUT/(pid+suffix)
                if not target.is_file() or target.stat().st_size==0:
                    raise RuntimeError('Expected export missing: '+str(target))
            report.append('PASS '+part+' -> '+pid+'_INTERMEDIATE.fbx')
        except Exception as exc:
            report.append('FAIL '+part+': '+repr(exc))
            (OUTPUT/'BATCH_EXPORT_REPORT.txt').write_text('\n'.join(report)+'\n',encoding='utf-8')
            traceback.print_exc()
            raise
    (OUTPUT/'BATCH_EXPORT_REPORT.txt').write_text('\n'.join(report)+'\n',encoding='utf-8')
    upload_zip=OUTPUT/'RoosterWorks_StationSupport_Five_FBXS.zip'
    with ZipFile(upload_zip,'w',ZIP_DEFLATED) as archive:
        for part in PARTS:
            pid={'OCTO_MEDIUM':'RW_OctoSupport_Medium','HEX_LONG':'RW_HexSupport_Long',
                 'HEX_MEDIUM':'RW_HexSupport_Medium','OCTO_25_ADAPTER':'RW_Octo25_Adapter',
                 'HEX_125_ADAPTER':'RW_Hex125_Adapter'}[part]
            file=OUTPUT/(pid+'_INTERMEDIATE.fbx')
            archive.write(file,file.name)
        archive.write(OUTPUT/'BATCH_EXPORT_REPORT.txt','BATCH_EXPORT_REPORT.txt')
    print('[RoosterWorks] ONE ZIP FOR UPLOAD:',upload_zip)
    print('\n[RoosterWorks] COMPLETE. Files in:',OUTPUT)
    for line in report: print(line)
    print('[RoosterWorks] Upload the FIVE FBX files here for KSP conversion, or use the supplied converter.')

run()
